#!/usr/bin/env python3
"""
Round 206o (culprits), 14 October 2026. Needs round 205o.

Moon and Mars: globes first, looks, timeline, grouped marks. 3D terrain under Standard.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 206o (14 October)\n\nNeeds round 205o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- 3D terrain: its tick now sits under Standard in the Basemap column;\n  "Moving the map in 3D" is a line under it that opens the notes the box\'s\n  whole width (terrainUnderBasemaps). Its old box is put away.\n- Headings "To the Moon" and "To Mars"; "Back to the map" is "Back to Earth".\n- map/bodies.html rewritten:\n  - opens on the globe; no Moon/Mars buttons on the page (the main map\'s\n    top right has them);\n  - a top right box like Earth\'s: Basemap (Satellite, plus Earth\'s seven\n    looks, made by recolouring NASA\'s picture, with a grid for Hologram and\n    Standard), View (Globe, Flat map) and Snap back to global scale;\n  - a timeline of years under the rows (rover stops dated from their sol;\n    Artemis III plans shown only at the far end, "today");\n  - marks that would sit on each other are drawn as one with a count; a\n    click lists every one, each opening to its own box, with "Zoom in to\n    part them";\n  - the globe picture is loaded before use and a failure is said in the\n    panel; the globe stops drawing while the flat map is shown.\n\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round206o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 205o" not in h.read_text(encoding="utf-8"):
        sys.exit("round206o: round 205o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round206o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/bodies.html", "map/test.mjs", check=False)
            sys.exit("round206o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round206o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
